 let items=[];try{items=$(name).all().map(x=>x.json||{});}catch(e){}
 for(const j of items){
  const organic=j.organic||j.data?.organic||j.results?.organic||j.data?.results?.organic||[];
  const rows=Array.isArray(organic)?organic:Object.values(organic||{});
  for(const r of rows){
