function extractText(v, depth = 0) {
  if (depth > 8 || v == null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(x => extractText(x, depth + 1)).filter(Boolean).sort((a, b) => b.length - a.length)[0] || '';
  if (typeof v !== 'object') return '';
  const keys = Object.keys(v);
  if (keys.length && keys.every(k => /^\d+$/.test(k))) {
    return keys.sort((a, b) => Number(a) - Number(b)).map(k => typeof v[k] === 'string' ? v[k] : '').join('');
  }
  for (const k of ['markdown', 'content', 'body', 'text', 'data', 'response']) {
    if (typeof v[k] === 'string' && v[k].length > 500) return v[k];
  }
  return Object.values(v).map(x => extractText(x, depth + 1)).filter(Boolean).sort((a, b) => b.length - a.length)[0] || '';
}
const refs = $('Extract Fallback URLs').all().map(x => x.json || {});
const pages = $input.all().map(x => x.json);
const sources = [];
