const commercial = d => /(salesforce\.com|timerni\.com|zapier\.com|make\.com|n8n\.io|hubspot\.com|microsoft\.com|google\.com|canva\.com|airtable\.com|notion\.so|clickup\.com|asana\.com|openai\.com|anthropic\.com|godaddy\.com|bill\.com)/i.test(d);
for (let i = 0; i < refs.length; i++) {
  const ref = refs[i] || {};
  const page = pages[i];
  let content = extractText(page)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (content.length < 500 || /^(502 Bad Gateway|403 Forbidden|Access Denied)/i.test(content)) continue;
  const domain = String(ref.domain || ((ref.url || '').match(/^https?:\/\/([^/]+)/i) || [])[1] || '').replace(/^www\./i, '').toLowerCase();
  const sourceType = community(domain) ? 'community_discussion' : commercial(domain) ? 'vendor_official' : 'independent_blog';
  const chunks = content.split(/(?<=[.!?])\s+(?=[A-Z])/).map(s => s.trim()).filter(s => s.length >= 100);
  const scored = chunks.map((s, index) => {
    const lower = s.toLowerCase();
    let score = 0;
    if (/i use|i used|we use|we used|we tried|i tried|my business|our business|in practice|experience|lesson learned|failed|failure|frustrat|difficult|maintenance|workaround|limitation|drawback|overkill|regret|wish i knew|too complicated|more work/.test(lower)) score += 4;
    if (/automation|workflow|small business|setup|time|process/.test(lower)) score += 2;
