    return { s, index, score };
  }).sort((a, b) => b.score - a.score || a.index - b.index);
  const selected = scored.slice(0, 5).sort((a, b) => a.index - b.index).map(x => x.s);
  const excerpt = (selected.join(' ') || content.slice(0, 2400)).slice(0, 3200);
  const firstPerson = /\b(i|we|my|our)\s+(use|used|tried|switched|found|struggle|struggled|recommend|prefer|stopped|built|automated|learned|experienced)\b/i.test(excerpt);
  const experienceType = sourceType === 'vendor_official' ? 'vendor_claim' : community(domain) ? 'community_opinion' : firstPerson ? 'first_hand' : 'reviewer_analysis';
  sources.push({ url: ref.url || '', title: ref.title || '', domain, source_type: sourceType, experience_type: experienceType, evidence_excerpt: excerpt, content_length: content.length, fetch_succeeded: true });
