if(draft!=='true')throw new Error('PRE-REVIEW GATE: article must remain draft:true until publication.');
if(!['ai-saas','automation','troubleshooting'].includes(category))throw new Error('PRE-REVIEW GATE: unsupported Prismbyte category.');
const allowed=['ai-saas','automation','troubleshooting'];
const [year,month,day]=publishDate.split('-').map(Number);
const dayOfYear=Math.floor((Date.UTC(year,month-1,day)-Date.UTC(year,0,0))/86400000);
const requiredCategory=allowed[(dayOfYear-1)%allowed.length];
if(category!==requiredCategory)throw new Error('PRE-REVIEW GATE: article category does not match today’s rotation ('+requiredCategory+').');
if(!/^https:\/\//i.test(image))throw new Error('PRE-REVIEW GATE: featured image must be a valid HTTPS URL.');
const sourceIndex=lines.findIndex(x=>x.trim()==='sources:');
const sources=[];
if(sourceIndex>=0)for(let i=sourceIndex+1;i<lines.length;i++){if(!/^\s+-\s+/.test(lines[i]))break;const u=lines[i].replace(/^\s+-\s+/,'').trim().replace(/^["']|["']$/g,'');if(u)sources.push(u);}
if(sources.length<2||sources.some(u=>!/^https:\/\//i.test(u)))throw new Error('PRE-REVIEW GATE: at least two valid HTTPS source URLs are required.');
const affiliateAudit=r.affiliate_audit||r.affiliate_summary||{};
const affiliateCount=Number(affiliateAudit.affiliate_link_count||0);
if(!['true','false'].includes(disclosure))throw new Error('PRE-REVIEW GATE: affiliateDisclosure must be true or false.');
if((affiliateCount>0)!==(disclosure==='true'))throw new Error('PRE-REVIEW GATE: affiliate disclosure does not match the verified affiliate-link audit.');
if(affiliateCount>0&&affiliateAudit.verified_in_final_article!==true)throw new Error('PRE-REVIEW GATE: affiliate links were not verified in the final article.');
const slug=title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
if(!slug)throw new Error('PRE-REVIEW GATE: safe article slug could not be generated.');
const summary=['PRISMBYTE PRE-REVIEW QUALITY CHECKS','Editorial QA: PASS','Article completeness: PASS','Factual accuracy: PASS','Source support: PASS','Editorial quality: PASS','Frontmatter and publish date: PASS','Category rotation: PASS ('+category+')','Featured image metadata: PASS','Source URLs: PASS ('+sources.length+')','Affiliate disclosure audit: PASS','Duplicate slug check: pending immediately before delivery'].join('\n');
return [{json:{...r,topic:String(r.research_summary?.topic||r.topic||title),articleMarkdown:article,qa_status:'PASS',qaPackagePreserved:true,duplicateCheckPassed:false,slug,source_urls_json:JSON.stringify(sources),request_id:String(r.request_id||''),qa_summary:summary,production_review_ready:true,production_category:category,affiliate_disclosure_enabled:affiliateCount>0}}];

const rows=$input.all().map(x=>x.json||{}).filter(r=>r.article_id&&r.review_status==='pending_review'&&r.qa_status==='PASS');
rows.sort((a,b)=>Date.parse(b.createdAt||b.review_sent_at||0)-Date.parse(a.createdAt||a.review_sent_at||0));
const older=rows.slice(1);
if(!older.length)return [{json:{article_id:'__NO_OLDER_PENDING__',skipUpdate:true}}];
return older.map(r=>({json:{article_id:String(r.article_id),skipUpdate:false}}));

let p=null;
try{p=$('Apply Retrieved Image Metadata').first().json;}catch(e){}
if(!p){try{p=$('Apply Generated Image Metadata').first().json;}catch(e){}}
if(!p)throw new Error('Affiliate matching could not recover the article and image metadata.');
const rawItem=$input.first()?.json||{};
const registryText=String(rawItem.data||rawItem.body||rawItem.text||'');
if(registryText.length<30)throw new Error('Live affiliate registry could not be loaded; refusing to infer offers.');
const records=[];
const blocks=registryText.match(/\{[^{}]*slug\s*:[^{}]*\}/gs)||[];
for(const block of blocks){
 const get=key=>{const m=new RegExp(key + "\\s*:\\s*(['\"])(.*?)\\1","s").exec(block);return m?m[2]:'';};
 const slug=get('slug'),name=get('name'),destinationUrl=get('destinationUrl');
 const approved=/approved\s*:\s*true/.test(block),active=/active\s*:\s*true/.test(block);
 if(slug&&name&&/^https:\/\//i.test(destinationUrl))records.push({slug,name,destinationUrl,approved,active});
}
if(!records.length)throw new Error('No valid affiliate records were parsed from the live registry.');
return [{json:{...p,affiliate_registry:records,affiliate_registry_loaded:true}}];

const base=$('Prepare Affiliate Agent Input').first()?.json||{};
let article=String(base.article||'');
if(!article)throw new Error('Affiliate fallback could not recover the article.');
const eligible=(base.affiliate_registry||[]).filter(o=>o.approved===true&&o.active===true&&/^https:\/\//i.test(String(o.destinationUrl||'')));
const includesUrl=(text,url)=>String(text||'').includes(url)||String(text||'').includes(url.replace(/&/g,'&amp;'));
const links=eligible.filter(o=>includesUrl(article,o.destinationUrl));
article=article.replace(/^affiliateDisclosure:\s*.*$/m,'affiliateDisclosure: '+(links.length?'true':'false'));
if(!/^affiliateDisclosure:/m.test(article))article=article.replace(/\n---\s*\n/,'\naffiliateDisclosure: '+(links.length?'true':'false')+'\n---\n');
return [{json:{...base,article,affiliate_audit:{registry_loaded:true,active_approved_offer_count:eligible.length,affiliate_link_count:new Set(links.map(o=>o.destinationUrl)).size,matched_offers:links.map(o=>({slug:o.slug,name:o.name,destinationUrl:o.destinationUrl})),skipped_offers:[],agent_provider:'none',agent_output_valid:false,agent_parse_error:'OpenRouter and NVIDIA affiliate matching agents failed; no new links were inserted.',verified_in_final_article:links.every(o=>includesUrl(article,o.destinationUrl)),reason:'Both AI matching attempts were unavailable. Continued safely with no new affiliate links.'}}}];
